const body = $input.first().json.body || $input.first().json;
const id = (body.id || Date.now()).toString().replace(/[^a-zA-Z0-9_-]/g, '');
const tema = body.tema || 'tecnologia';
const guionRaw = body.guion || '';

// Limpia etiquetas de dirección ([0-3s], [VISUAL], GANCHO:, etc.) para dejar solo lo narrable
const textoNarrable = guionRaw
  .replace(/\[.*?\]/g, '')
  .replace(/^(DURACIÓN|RITMO|TÍTULO VIRAL|GANCHO|BUCLE ABIERTO|DESARROLLO.*|CLÍMAX.*|ESCENAS|CIERRE.*):?/gim, '')
  .replace(/[*#_]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

// Extrae 2 palabras clave limpias para buscar B-Roll vertical en Pexels
const queryPexels = tema
  .replace(/[^a-zA-ZáéíóúÁÉÍÓÚñÑ0-9\s]/g, '')
  .split(' ')
  .filter(w => w.length > 3)
  .slice(0, 2)
  .join(' ') || 'technology';

return [{
  json: {
    id,
    tema,
    textoNarrable,
    queryPexels
  }
}];

const prep = $('Preparar Guion y Voz').first().json;
const pexels = $input.first().json;

const videos = pexels.videos || [];
let clipUrl = '';

if (videos.length > 0) {
  const files = videos[0].video_files || [];
  const hd = files.find(f => f.quality === 'hd' && f.height > f.width) || files[0];
  clipUrl = hd?.link || '';
}

return [{
  json: {
    ...prep,
    clipUrl
  }
}];
